 [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF-PAP-068", "label": "Study family SF-PAP-068: Opponent three-point luck has no persistent player component", "score": 0.739, "reached_via": ["FAM:SF36 auto_related_family (repeat_order_unknown) FAM:SF-PAP-068", "FAM:SF36 auto_related_family (record_link_related_to) FAM:SF-PAP-068"], "attributes": {"observed_research_question": "Opponent three-point luck has no persistent player component", "auto_outcome_status": "supported", "observed_hypothesis": "Opponent three-point luck is noise: split-half reliability ~0 and H1 does not predict H2.", "observed_result": "odd/even reliability: opp 3s 0.004; opp 2s 0.463; XNET 0.585; own luck 0.477; teammate luck 0.427; PM 0.549; H1 opp3 -> H2 opp3 per 100: +0.008 (SE 0.009); H1 opp2 -> H2: +0.009 (SE 0.009)", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "reliability 0.004; H1->H2 +0.008 SE 0.009", "observed_sample_and_power": "1,405 player-seasons; N=84,641 player-games", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "supported"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:low_measurement_reliability"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:MEASURE_RELIABILITY"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF36"}]}, {"id": "FAM:SF35", "label": "Study family SF35: Next-game playing-time response to opponent 3P luck (carryover)", "score": 0.739, "reached_via": ["FAM:SF36 auto_related_family (repeat_order_unknown) FAM:SF35", "FAM:SF36 auto_related_family (repeat_order_unknown) FAM:SF35"], "attributes": {"observed_research_question": "Next-game playing-time response to opponent 3P luck (carryover)", "auto_outcome_status": "artifact", "observed_hypothesis": "Game-N opponent 3P luck while on court changes a player's game N+1 share and starting status.", "observed_result": ["[CHT-070] Opp 3P luck next-game share +0.063 (0.018); holding Game N role +0.002 (0.018). Start prob +0.0004 (0.0003) n.s. 1 SD (6.0 points) ~11 seconds. Own FG luck carry-over +0.113 (0.023) survives. Verdict KILL for t [cut; read_family for the full text]", "[TMP-011] G_opp3 +0.0625 (0.0180), shuffle null -0.0002 sd 0.0159 p 0.000; starting +0.00041 (0.00027) perm p 0.150/0.630; controlling game-N share G_opp3 +0.0020 (0.0178); adding expected opp 3P pts +0.0284 (0.0179); bi [cut; read_family for the full text]"], "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:insufficient_exposure"}]}, {"id": "FAM:SF36", "label": "Study family SF36: Halftime minute change weights noise like information", "score": 0.739, "reached_via": ["request matches the question or hypothesis of FAM:SF36 (0.74)"], "attributes": {"observed_research_question": "Halftime minute change weights noise like information", "auto_outcome_status": "supported", "observed_hypothesis": "A point of opponent three-point luck moves second-half possession share less than a point of opponent two-point luck or expected net points.", "observed_result": ["[PAP-069] opp3 0.134 (SE 0.027); opp2 0.136 (SE 0.034); XNET 0.094 (SE 0.029); opp3-opp2=-0.002 (SE 0.043); opp3-XNET=+0.041 (SE 0.040); own FG luck 0.511 (SE 0.029); raw PM 0.144 (SE 0.013); 1 SD opp3 (4.39 pts) ~0.59 p [cut; read_family for the full text]", "[PAP-070] league-wide shuffle mean 0.003 (SD 0.020); within game+defense 0.029 (SD 0.017); observed 0.131; none of 200 draws reached 0.131; next-game luck -0.005 (SE 0.020) vs this-game 0.112 (SE 0.022); Q1->Q2 0.193 (SE [cut; read_family for the full text]"], "auto_failure_mechanism": "D_positive (no failure: positive result)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}]}, {"id": "FAM:SF-PAP-028", "label"